<template><div class="admin-page"><header><span class="eyebrow">管理员端</span><h1>用户与角色</h1><p>角色决定工作台入口和批次操作范围。</p></header><section class="panel"><div v-for="user in users" :key="user.user_id" class="user-row"><div><strong>{{user.username}}</strong><small>{{user.phone}} · 当前：{{(user.roles||[]).map(r=>r.name).join('、')||'未分配'}}</small></div><div class="role-actions"><label v-for="role in roles" :key="role.code" class="role-check"><input type="checkbox" :value="role.code" v-model="selections[user.user_id]">{{role.name}}</label><button @click="save(user.user_id)">保存</button></div></div><p v-if="message" class="message">{{message}}</p></section></div></template>
<script>
import axios from 'axios'; import {API_BASE} from '@/config/api';
export default{data:()=>({users:[],roles:[],selections:{},message:''}),async mounted(){await Promise.all([this.loadUsers(),this.loadRoles()]);},methods:{async loadUsers(){const r=await axios.get(`${API_BASE}/admin/users/`);this.users=r.data.data||[];this.users.forEach(u=>{this.selections[u.user_id]=(u.roles||[]).map(x=>x.code);});},async loadRoles(){const r=await axios.get(`${API_BASE}/roles/`);this.roles=r.data.data||[];},async save(id){try{await axios.post(`${API_BASE}/users/${id}/roles/`,{roles:this.selections[id],primary_role:this.selections[id][0]});this.message='角色已更新';await this.loadUsers();}catch(e){this.message=e.response?.data?.msg||'角色更新失败';}}}};
</script>
<style scoped>.admin-page{max-width:1080px;margin:auto}.eyebrow{font-size:12px;color:#27865a;font-weight:700}.admin-page h1{margin:7px 0;color:#1b583c}.admin-page header p{color:#789081;font-size:13px}.panel{background:#fff;border:1px solid #dcebe1;border-radius:12px;padding:6px 16px}.user-row{display:flex;justify-content:space-between;gap:18px;align-items:center;border-bottom:1px solid #edf3ee;padding:15px 0}.user-row:last-child{border:0}.user-row small{display:block;margin-top:5px;color:#82988b;font-size:12px}.role-actions{display:flex;flex-wrap:wrap;align-items:center;gap:8px;justify-content:flex-end}.role-check{font-size:12px;color:#486956}.role-check input{accent-color:#1f8758;margin-right:3px}.role-actions button{border:0;border-radius:6px;background:#1f8758;color:#fff;padding:7px 10px}.message{color:#2b8258;font-size:13px}@media(max-width:700px){.user-row{display:block}.role-actions{justify-content:flex-start;margin-top:10px}}
</style>
